cat <<'EOF' > tmux_script.py
import libtmux
import time
import os

def capture_time(lib):
    os.system('tmux kill-server')
    server = libtmux.Server()
    session = server.new_session(session_name="ttyclock")
    window = session.windows[0]
    pane = window.panes[0]

    pane.send_keys(f'LD_PRELOAD={lib} ./executable -s', enter=True)
    time.sleep(1.2)
    content = pane.cmd('capture-pane', '-e', '-p').stdout
    session.kill()
    return content

for lib in ['./lib1.so', './lib2.so']:
    content = capture_time(lib)
    for line in content:
        res = ''
        in_green = False
        i = 0
        while i < len(line):
            if line[i:i+5] == '\x1b[42m':
                in_green = True
                i += 5
            elif line[i:i+5] == '\x1b[49m':
                in_green = False
                i += 5
            elif line[i:i+4] == '\x1b[32m' or line[i:i+4] == '\x1b[39m':
                i += 4
            else:
                res += '#' if in_green and line[i] == ' ' else line[i]
                i += 1
        print(res)
EOF
python3 tmux_script.py"}

