int win_w = 80, win_h = 24;
int pos_x = 0, pos_y = 0;
int dir_x = 1, dir_y = 1;
bool running = true;
bool colon_visible = true;
long frame_count = 0;

struct termios orig_termios;

const char *font[10][5] = {
    {"111111", "11  11", "11  11", "11  11", "111111"},
    {"    11", "    11", "    11", "    11", "    11"},
    {"111111", "    11", "111111", "11    ", "111111"},
