    {"11  11", "11  11", "111111", "    11", "    11"},
    {"111111", "11    ", "111111", "    11", "111111"},
    {"111111", "11    ", "111111", "11  11", "111111"},
    {"111111", "    11", "    11", "    11", "    11"},
    {"111111", "11  11", "111111", "11  11", "111111"},
    {"111111", "11  11", "111111", "    11", "111111"}
};

void sigwinch(int sig) {
    struct winsize w;
    ioctl(STDOUT_FILENO, TIOCGWINSZ, &w);
    win_w = w.ws_col;
    win_h = w.ws_row;
}

void sigterm(int sig) { running = false; }

void reset_terminal() {
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
    printf("\033[?25h\033[?1049l\033[0m\033[2J\033[H");
    fflush(stdout);
}

void gotoxy(int x, int y) { printf("\033[%d;%dH", y + 1, x + 1); }

void draw_digit(int digit, int x, int y) {
    for (int r = 0; r < 5; r++) {
        gotoxy(x, y + r);
        int c = 0;
        while (c < 6) {
            if (font[digit][r][c] == '1') {
                int len = 0;
                while (c + len < 6 && font[digit][r][c + len] == '1') len++;
                if (is_bold) printf("\033[5m\033[%dm", 40 + clock_color);
                else printf("\033[%dm", 40 + clock_color);
                for (int i = 0; i < len; i++) putchar(' ');
                if (is_bold) printf("\033[0m\033[39m\033[49m");
                else printf("\033[49m");
                c += len;
            } else {
                int len = 0;
                while (c + len < 6 && font[digit][r][c + len] == ' ') len++;
                for (int i = 0; i < len; i++) putchar(' ');
                c += len;
            }
        }
    }
}

void draw_colon(int x, int y) {
    for (int r = 0; r < 5; r++) {
        gotoxy(x, y + r);
        if ((r == 1 || r == 3) && colon_visible) {
            if (is_bold) printf("\033[5m\033[%dm  \033[0m\033[39m\033[49m", 40 + clock_color);
            else printf("\033[%dm  \033[49m", 40 + clock_color);
        } else {
            printf("  ");
        }
    }
}

int main(int argc, char **argv) {
    int opt_c;
    while ((opt_c = getopt(argc, argv, "iuvsScbtrahDBxnC:f:d:a:T:")) != -1) {
        switch (opt_c) {
            case 'i': printf("TTY-Clock 2 © by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)\n"); return 0;
            case 'v': printf("TTY-Clock 2 © devel version\n"); return 0;
            case 'h': printf("usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] \n    -s            Show seconds                                   \n    -S            Screensaver mode                               \n    -x            Show box                                       \n    -c            Set the clock at the center of the terminal    \n    -C [0-7]      Set the clock color                            \n    -b            Use bold colors                                \n    -t            Set the hour in 12h format                     \n    -u            Use UTC time                                   \n    -T tty        Display the clock on the specified terminal    \n    -r            Do rebound the clock                           \n    -f format     Set the date format                            \n    -n            Don't quit on keypress                         \n    -v            Show tty-clock version                         \n    -i            Show some info about tty-clock                 \n    -h            Show this page                                 \n    -D            Hide date                                      \n    -B            Enable blinking colon                          \n    -d delay      Set the delay between two redraws of the clock. Default 1s. \n    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n"); return 0;
            case 'u': utc = true; break;
            case 's': show_sec = true; break;
            case 'S': screensaver = true; break;
            case 'c': centered = true; break;
            case 'b': is_bold = true; break;
            case 't': fmt_12h = true; break;
            case 'r': rebound = true; break;
            case 'D': hide_date = true; break;
            case 'B': blink_colon = true; break;
            case 'x': show_box = true; break;
            case 'n': no_quit = true; break;
            case 'C': clock_color = atoi(optarg); break;
            case 'f': fmt_date = optarg; break;
            case 'd': delay_s = atol(optarg); break;
            case 'a': delay_ns = atol(optarg); break;
            case 'T': tty_dev = optarg; break;
        }
    }

    if (tty_dev) {
        int fd = open(tty_dev, O_RDWR);
        if (fd >= 0) {
            dup2(fd, STDIN_FILENO);
            dup2(fd, STDOUT_FILENO);
            dup2(fd, STDERR_FILENO);
            close(fd);
        }
    }

    tcgetattr(STDIN_FILENO, &orig_termios);
    struct termios t = orig_termios;
    t.c_lflag &= ~(ICANON | ECHO);
    t.c_cc[VMIN] = 1;
    t.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &t);

    printf("\033[?1049h\033[2J\033[H\033[?25l");
    fflush(stdout);

    struct sigaction sa;
    sa.sa_handler = sigwinch;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGWINCH, &sa, NULL);

    sa.sa_handler = sigterm;
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);

    sigwinch(0);
    srand(time(NULL));

    while (running) {
        struct timeval tv_now;
        gettimeofday(&tv_now, NULL);
        if (blink_colon) {
            colon_visible = (tv_now.tv_sec % 2) == 0;
        }

        int w_clock = show_sec ? 51 : 32;
        int clock_h = 5;

        int max_x = win_w - w_clock - 2;
        int max_y = win_h - 8;
        if (max_x < 1) max_x = 1;
        if (max_y < 1) max_y = 1;

        if (centered) {
            pos_x = (win_w - w_clock) / 2;
            pos_y = (win_h / 2) - 2; 
        } else if (rebound) {
            if (pos_x < 1 || pos_x > max_x) dir_x = -dir_x;
            if (pos_y < 1 || pos_y > max_y) dir_y = -dir_y;
            pos_x += dir_x;
            pos_y += dir_y;
        }

        if (pos_x < 1) pos_x = 1;
        if (pos_x > max_x) pos_x = max_x;
        if (pos_y < 1) pos_y = 1;
        if (pos_y > max_y) pos_y = max_y;

        printf("\033[2J");

        time_t t_now = tv_now.tv_sec;
        struct tm *tm_info = utc ? gmtime(&t_now) : localtime(&t_now);

        int h = tm_info->tm_hour;
        if (fmt_12h) {
            h = h % 12;
            if (h == 0) h = 12;
        }

        int digits[6];
        digits[0] = h / 10;
        digits[1] = h % 10;
        digits[2] = tm_info->tm_min / 10;
        digits[3] = tm_info->tm_min % 10;
        digits[4] = tm_info->tm_sec / 10;
        digits[5] = tm_info->tm_sec % 10;

        if (show_box) {
            printf("\033(0");
            int bx = pos_x - 1;
            int by = pos_y - 1;
            int bw = w_clock + 2;

            gotoxy(bx, by);
            putchar('l');
            for(int i=0; i<bw-2; i++) putchar('q');
            putchar('k');

            for(int i=0; i<clock_h; i++) {
                gotoxy(bx, by + 1 + i); putchar('x');
                gotoxy(bx + bw - 1, by + 1 + i); putchar('x');
            }

            gotoxy(bx, by + clock_h + 1);
            putchar('m');
            for(int i=0; i<bw-2; i++) putchar('q');
            putchar('j');
            printf("\033(B");
        }

        int dx = pos_x;
        draw_digit(digits[0], dx, pos_y); dx += 7;
        draw_digit(digits[1], dx, pos_y); dx += 8;
        draw_colon(dx, pos_y); dx += 4;
        draw_digit(digits[2], dx, pos_y); dx += 7;
        draw_digit(digits[3], dx, pos_y); dx += 8;

        if (show_sec) {
            draw_colon(dx, pos_y); dx += 4;
            draw_digit(digits[4], dx, pos_y); dx += 7;
            draw_digit(digits[5], dx, pos_y);
        }

        if (!hide_date) {
            char date_str[256];
            strftime(date_str, sizeof(date_str), fmt_date, tm_info);
            if (fmt_12h) {
                char ampm[16];
                strftime(ampm, sizeof(ampm), " [%p]", tm_info);
                strcat(date_str, ampm);
            }

            int date_len = strlen(date_str);
            int box_w = w_clock + 2;
            int date_x = pos_x - 1 + (box_w - date_len) / 2;
            int date_y = pos_y + clock_h + 1; // 6 lines below pos_y

            if (show_box) {
                printf("\033(0");
                if (centered) {
                    gotoxy(date_x - 1, date_y - 1);
                    putchar('l');
                    for(int i=0; i<date_len; i++) putchar('q');
                    putchar('k');
                }

                gotoxy(date_x - 1, date_y); putchar('x');
                gotoxy(date_x + date_len, date_y); putchar('x');

                gotoxy(date_x - 1, date_y + 1);
                putchar('m');
                for(int i=0; i<date_len; i++) putchar('q');
                putchar('j');
                printf("\033(B");
            }

            gotoxy(date_x, date_y);
            if (is_bold) printf("\033[1m\033[%dm%s\033[0m\033[39m\033[49m", 30 + clock_color, date_str);
            else printf("\033[%dm%s\033[39m", 30 + clock_color, date_str);
        }

        fflush(stdout);

        struct timeval tv;
        tv.tv_sec = delay_s;
        tv.tv_usec = delay_ns / 1000;

        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(STDIN_FILENO, &rfds);

        int res = select(STDIN_FILENO + 1, &rfds, NULL, NULL, &tv);
        if (res > 0) {
            char c;
            if (read(STDIN_FILENO, &c, 1) == 1) {
                if (screensaver && !no_quit) running = false;
                else {
                    switch (c) {
                        case 'q':
                        case 'Q':
                            if (!no_quit) running = false;
                            break;
                        case 'k': case 'K': if(!centered) pos_y--; dir_y = -1; break;
                        case 'j': case 'J': if(!centered) pos_y++; dir_y = 1; break;
                        case 'h': case 'H': if(!centered) pos_x--; dir_x = -1; break;
                        case 'l': case 'L': if(!centered) pos_x++; dir_x = 1; break;
                        case 'c': case 'C': centered = !centered; break;
                        case 'r': case 'R': rebound = !rebound; break;
                        case 's': case 'S': show_sec = !show_sec; break;
                        case 't': case 'T': fmt_12h = !fmt_12h; break;
                        case 'x': case 'X': show_box = !show_box; break;
                        case 'b': case 'B': is_bold = !is_bold; break;
                        case 'D': hide_date = !hide_date; break;
                        case '0' ... '7': clock_color = c - '0'; break;
                    }
                }
            }
        }
    }

    reset_terminal();
    return 0;
}
